/* Session overlays of the loaded battle banks (docs/modding/tables.md
 * "Session bank overlays"). The table service owns the banks and their exact
 * extents; an overlay copies a mod's generated bytes over a whole bank at a
 * frame safe point and the session-end restore copies the captured stock back. */
#include "p4pc/game_table_overlay.h"
#include "p4pc/game_table_extents.h"
#include "p4pc/gmem.h"
#include "p4pc/mod_save.h"
#include "p4pc/ps2_libc.h"
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* The actual SLUS_217.82 0x005f66c0 descriptors: file labels, block order and
 * the GP slot each block's base is stored in. */
static const P4TableOverlayInfo banks[P4_TABLE_OVERLAY_BANKS] = {
    {"SKILL0", "battle/SKILL.TBL", 0, 0x007644a4u, 0, 0, 0, 0},
    {"SKILL1", "battle/SKILL.TBL", 1, 0x007644a8u, 0, 0, 0, 0},
    {"UNIT0", "battle/UNIT.TBL", 0, 0x007644b4u, 1, 0, 0, 0},
    {"UNIT1", "battle/UNIT.TBL", 1, 0x007644b8u, 1, 0, 0, 0},
    {"UNIT2", "battle/UNIT.TBL", 2, 0x007644c8u, 1, 0, 0, 0},
    {"MSG0", "battle/MSG.TBL", 0, 0x0076453cu, 0, 0, 0, 0},
    {"MSG1", "battle/MSG.TBL", 1, 0x00764538u, 0, 0, 0, 0},
    {"MSG2", "battle/MSG.TBL", 2, 0x00764534u, 0, 0, 0, 0},
    {"MSG3", "battle/MSG.TBL", 3, 0x00764530u, 0, 0, 0, 0},
    {"MSG4", "battle/MSG.TBL", 4, 0x0076452cu, 0, 0, 0, 0},
    {"PERSONA0", "battle/PERSONA.TBL", 0, 0x007644c4u, 1, 0, 0, 0},
    {"PERSONA1", "battle/PERSONA.TBL", 1, 0x007644ccu, 1, 0, 0, 0},
    {"PERSONA2", "battle/PERSONA.TBL", 2, 0x007644d4u, 0, 0, 0, 0},
    {"PERSONA3", "battle/PERSONA.TBL", 3, 0x007644d8u, 0, 0, 0, 0},
    {"PERSONA4", "battle/PERSONA.TBL", 4, 0x007644dcu, 0, 0, 0, 0},
    {"PERSONA5", "battle/PERSONA.TBL", 5, 0x007644e0u, 0, 0, 0, 0},
    {"ENCOUNT0", "battle/ENCOUNT.TBL", 0, 0x00764504u, 1, 0, 0, 0},
    {"ENCOUNT1", "battle/ENCOUNT.TBL", 1, 0x0076450cu, 1, 0, 0, 0},
    {"ENCOUNT2", "battle/ENCOUNT.TBL", 2, 0x00764510u, 1, 0, 0, 0},
    {"ENCOUNT3", "battle/ENCOUNT.TBL", 3, 0x00764508u, 1, 0, 0, 0},
    {"ENCOUNT4", "battle/ENCOUNT.TBL", 4, 0x00764514u, 1, 0, 0, 0},
    {"EFFECT0", "battle/EFFECT.TBL", 0, 0x007644acu, 0, 0, 0, 0},
    {"MODEL0", "battle/MODEL.TBL", 0, 0x007644b0u, 0, 0, 0, 0},
    {"MODEL1", "battle/MODEL.TBL", 1, 0x007644bcu, 0, 0, 0, 0},
    {"MODEL2", "battle/MODEL.TBL", 2, 0x007644d0u, 0, 0, 0, 0},
    {"AICALC0", "battle/AICALC.TBL", 0, 0x007644e4u, 0, 0, 0, 0},
    {"AICALC1", "battle/AICALC.TBL", 1, 0x007644e8u, 0, 0, 0, 0},
    {"AICALC2", "battle/AICALC.TBL", 2, 0x007644ecu, 0, 0, 0, 0},
    {"AICALC3", "battle/AICALC.TBL", 3, 0x007644f0u, 0, 0, 0, 0},
    {"AICALC4", "battle/AICALC.TBL", 4, 0x007644f4u, 0, 0, 0, 0},
    {"AICALC5", "battle/AICALC.TBL", 5, 0x007644f8u, 0, 0, 0, 0},
    {"AICALC6", "battle/AICALC.TBL", 6, 0x007644fcu, 0, 0, 0, 0},
    {"AICALC7", "battle/AICALC.TBL", 7, 0x00764500u, 0, 0, 0, 0},
    {"AICALC8", "battle/AICALC.TBL", 8, 0x007644c0u, 0, 0, 0, 0},
    {"AICALC9", "battle/AICALC.TBL", 9, 0x00764518u, 0, 0, 0, 0},
    {"AICALC10", "battle/AICALC.TBL", 10, 0x0076451cu, 0, 0, 0, 0},
    /* The arcana fusion charts fclFusePair (0x003124a0) and fclFuseTripleArcana
     * (0x00311ea0) read as [low * 24 + high] for arcana 1..22: the span from
     * cell (1,1) to cell (22,22) of each 24-byte-row chart. Results are arcana
     * 1..22 or 0 (no fusion). */
    {"FUSION0", "D_00642147 pair chart", 0, 0, 1, 0x00642147u + 25u, 526u, 22u},
    {"FUSION1", "D_00642387 alternate pair chart", 0, 0, 1, 0x00642387u + 25u, 526u, 22u},
    {"FUSION2", "D_00642727 triangle chart", 0, 0, 1, 0x00642727u + 25u, 526u, 22u},
    {"FUSION3", "D_00642967 alternate triangle chart", 0, 0, 1, 0x00642967u + 25u, 526u, 22u},
    /* The retail item table as the game reads it (API 1.11): the init copy in
     * D_0079bf00 after its 16-byte header, 1536 rows of 68 bytes, while the
     * item pointer 0x007642a0 names it (an item catalog publishes its own base).
     * Only each row's unlock gates may change: datItemMoonGateFirst/Second,
     * the words at +0x3c and +0x40 the shop lists test. */
    {"ITEMTBL", "D_0079bf10 item table", 0, 0, 1, 0x0079bf10u, 1536u * 68u, 0u, 0x007642a0u, 68u, 0x3cu, 8u},
};
/* The battle state pointer (gp 0xb3ac): nonzero from battle setup to teardown. */
#define BATTLE_STATE 0x0076449cu
#define NO_OWNER ((size_t)-1)

typedef struct Overlay {
    size_t owner;
    char owner_name[64];
    uint32_t base, bytes;
    uint8_t *stock, *layer;
} Overlay;
static Overlay overlays[P4_TABLE_OVERLAY_BANKS];
static P4ModSaveRegistration *session_registration;

const P4TableOverlayInfo *p4_game_tables_overlay_info(unsigned index)
{
    return index < P4_TABLE_OVERLAY_BANKS ? &banks[index] : NULL;
}
const P4TableOverlayInfo *p4_game_tables_overlay_find(const char *key)
{
    for (unsigned i = 0; key && i < P4_TABLE_OVERLAY_BANKS; ++i)
        if (!strcmp(banks[i].key, key)) return &banks[i];
    return NULL;
}
static unsigned bank_index(const P4TableOverlayInfo *bank)
{
    return bank >= banks && bank < banks + P4_TABLE_OVERLAY_BANKS ? (unsigned)(bank - banks) : P4_TABLE_OVERLAY_BANKS;
}
static int retail_catalog(void)
{
    uint8_t identity[32];
    return p4_game_table_catalog_identity(identity) == 0;
}
int p4_game_tables_overlay_extent(const P4TableOverlayInfo *bank, uint32_t *base, uint32_t *bytes)
{
    uint32_t rows = 0;
    if (bank_index(bank) == P4_TABLE_OVERLAY_BANKS || !base || !bytes) return 0;
    if (bank->address) {
        /* A pointer-guarded bank exists only while the game reads it there and
         * no package table source is published. */
        if (bank->pointer && (P4_G32(bank->pointer) != bank->address || !retail_catalog())) return 0;
        *base = bank->address;
        *bytes = bank->size;
        return 1;
    }
    if (!p4_game_table_extent_rows(bank->slot, 1, base, &rows)) return 0;
    *bytes = rows;
    return 1;
}
int p4_game_tables_overlay_stock(const P4TableOverlayInfo *bank, void *out, size_t capacity)
{
    uint32_t base = 0, bytes = 0;
    unsigned i = bank_index(bank);
    if (i == P4_TABLE_OVERLAY_BANKS || !out) return -1;
    if (overlays[i].layer) {
        if (capacity != overlays[i].bytes) return -1;
        memcpy(out, overlays[i].stock, capacity);
        return 0;
    }
    if (!p4_game_tables_overlay_extent(bank, &base, &bytes) || capacity != bytes) return -1;
    if (bytes) memcpy(out, P4_G2H(base), bytes);
    return 0;
}
size_t p4_game_tables_overlay_count(size_t owner)
{
    size_t count = 0;
    for (unsigned i = 0; i < P4_TABLE_OVERLAY_BANKS; ++i)
        if (overlays[i].layer && (owner == NO_OWNER || overlays[i].owner == owner)) ++count;
    return count;
}
const char *p4_game_tables_overlay_owner(const P4TableOverlayInfo *bank)
{
    unsigned i = bank_index(bank);
    return i < P4_TABLE_OVERLAY_BANKS && overlays[i].layer ? overlays[i].owner_name : NULL;
}

static void observe(void *user, uint32_t slot, uint32_t base, uint32_t bytes);
static void update_observer(void)
{
    p4_game_table_extent_observe(p4_game_tables_overlay_count(NO_OWNER) ? observe : NULL, NULL);
}
static void release(Overlay *overlay)
{
    free(overlay->stock);
    free(overlay->layer);
    *overlay = (Overlay){.owner = NO_OWNER};
}
/* Writes stock back only while the slot still names the overlaid bank; a bank
 * that moved was re-captured by the observer or no longer exists there. */
static void restore(unsigned i)
{
    Overlay *overlay = &overlays[i];
    uint32_t base = 0, bytes = 0;
    if (!overlay->layer) return;
    if (p4_game_tables_overlay_extent(&banks[i], &base, &bytes) && base == overlay->base && bytes == overlay->bytes &&
        bytes)
        func_0043f810(P4_G2H(base), overlay->stock, bytes);
    release(overlay);
}
/* A loader re-copy or a relocating commit of an overlaid slot: re-capture the
 * new bytes as stock and re-apply, or drop the overlay when its extent or the
 * catalog changed (never memcpy a layer sized for another extent). */
static void observe(void *user, uint32_t slot, uint32_t base, uint32_t bytes)
{
    (void)user;
    for (unsigned i = 0; i < P4_TABLE_OVERLAY_BANKS; ++i) {
        Overlay *overlay = &overlays[i];
        if (banks[i].slot != slot || !overlay->layer) continue;
        if (bytes != overlay->bytes || !retail_catalog() || base < 0x00100000u || base > 0x02000000u ||
            bytes > 0x02000000u - base) {
            fprintf(stderr, "p4pc: table overlay: %s of mod %s dropped: the bank was re-published with another "
                            "extent or catalog\n", banks[i].key, overlay->owner_name);
            release(overlay);
            continue;
        }
        overlay->base = base;
        if (bytes) {
            memcpy(overlay->stock, P4_G2H(base), bytes);
            func_0043f810(P4_G2H(base), overlay->layer, bytes);
        }
    }
    update_observer();
}
static int refuse(char *reason, size_t capacity, const char *format, ...)
{
    if (reason && capacity) {
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(reason, capacity, format, arguments);
        va_end(arguments);
    }
    return -1;
}
int p4_game_tables_overlay_apply(size_t owner, const char *owner_name,
    const P4TableOverlayBank *layer, size_t count, char *reason, size_t capacity)
{
    if (owner == NO_OWNER || !owner_name || strlen(owner_name) >= sizeof overlays[0].owner_name ||
        (count && !layer) || count > P4_TABLE_OVERLAY_BANKS)
        return refuse(reason, capacity, "invalid table overlay request");
    if (count && !session_registration)
        return refuse(reason, capacity, "the session-end table restore is not registered");
    if (count && !retail_catalog())
        return refuse(reason, capacity, "a package table source owns the battle banks in this session");
    /* Clearing writes stock back: a battle sees no change either way. */
    if (P4_G32(BATTLE_STATE) && (count || p4_game_tables_overlay_count(owner)))
        return refuse(reason, capacity, "battle banks cannot change during a battle");
    unsigned index[P4_TABLE_OVERLAY_BANKS];
    uint32_t base[P4_TABLE_OVERLAY_BANKS];
    uint8_t *copies[P4_TABLE_OVERLAY_BANKS][2];
    for (size_t j = 0; j < count; ++j) {
        const P4TableOverlayInfo *bank = p4_game_tables_overlay_find(layer[j].key);
        uint32_t bytes = 0;
        if (!bank) return refuse(reason, capacity, "unknown battle bank %s", layer[j].key ? layer[j].key : "(none)");
        if (!bank->overlayable) return refuse(reason, capacity, "battle bank %s cannot be overlaid", bank->key);
        index[j] = bank_index(bank);
        for (size_t k = 0; k < j; ++k)
            if (index[k] == index[j]) return refuse(reason, capacity, "battle bank %s is listed twice", bank->key);
        const Overlay *current = &overlays[index[j]];
        if (current->layer && current->owner != owner)
            return refuse(reason, capacity, "battle bank %s is overlaid by mod %s", bank->key, current->owner_name);
        if (!p4_game_tables_overlay_extent(bank, &base[j], &bytes) || !bytes)
            return refuse(reason, capacity, "battle bank %s is not loaded", bank->key);
        if (current->layer && (current->base != base[j] || current->bytes != bytes))
            return refuse(reason, capacity, "battle bank %s moved since its overlay", bank->key);
        if (!layer[j].bytes || layer[j].size != bytes)
            return refuse(reason, capacity, "overlay for %s does not match the bank's loaded size", bank->key);
        for (size_t k = 0; bank->byte_limit && k < bytes; ++k)
            if (((const uint8_t *)layer[j].bytes)[k] > bank->byte_limit)
                return refuse(reason, capacity, "overlay for %s has a value above %u", bank->key, bank->byte_limit);
        /* A field-restricted bank: outside each row's window every byte is stock. */
        const uint8_t *stock = current->layer ? current->stock : P4_G2H(base[j]);
        for (uint32_t k = 0; bank->row_stride && k < bytes; ++k) {
            const uint32_t column = k % bank->row_stride;
            if ((column < bank->field_offset || column >= bank->field_offset + bank->field_size) &&
                ((const uint8_t *)layer[j].bytes)[k] != stock[k])
                return refuse(reason, capacity, "overlay for %s changes row %u byte 0x%02x outside its fields",
                              bank->key, (unsigned)(k / bank->row_stride), (unsigned)column);
        }
    }
    /* Allocate everything before the first byte changes. */
    size_t failed = count;
    for (size_t j = 0; j < count; ++j) {
        const Overlay *current = &overlays[index[j]];
        copies[j][0] = current->layer ? NULL : malloc(layer[j].size);
        copies[j][1] = malloc(layer[j].size);
        if ((!current->layer && !copies[j][0]) || !copies[j][1]) { failed = j + 1; break; }
    }
    if (failed != count) {
        for (size_t j = 0; j < failed; ++j) { free(copies[j][0]); free(copies[j][1]); }
        return refuse(reason, capacity, "table overlay allocation failed");
    }
    /* Commit: drop the banks this owner no longer overlays, then write the layer. */
    for (unsigned i = 0; i < P4_TABLE_OVERLAY_BANKS; ++i) {
        if (!overlays[i].layer || overlays[i].owner != owner) continue;
        size_t j = 0;
        while (j < count && index[j] != i) ++j;
        if (j == count) restore(i);
    }
    for (size_t j = 0; j < count; ++j) {
        Overlay *overlay = &overlays[index[j]];
        if (!overlay->layer) {
            memcpy(copies[j][0], P4_G2H(base[j]), layer[j].size);
            overlay->stock = copies[j][0];
            overlay->owner = owner;
            snprintf(overlay->owner_name, sizeof overlay->owner_name, "%s", owner_name);
            overlay->base = base[j];
            overlay->bytes = (uint32_t)layer[j].size;
        } else free(overlay->layer);
        memcpy(copies[j][1], layer[j].bytes, layer[j].size);
        overlay->layer = copies[j][1];
        func_0043f810(P4_G2H(overlay->base), overlay->layer, overlay->bytes);
    }
    update_observer();
    return 0;
}
/* VM teardown only happens at process shutdown (selection changes are
 * restart-only), so restoring immediately, even mid-battle, is infallible and
 * never observed by a continuing battle. */
void p4_game_tables_overlay_clear_owner(size_t owner)
{
    for (unsigned i = 0; i < P4_TABLE_OVERLAY_BANKS; ++i)
        if (overlays[i].layer && overlays[i].owner == owner) restore(i);
    update_observer();
}
void p4_game_tables_overlay_static_published(uint32_t address, uint32_t bytes)
{
    /* Every boot publishes the retail table: without an overlay this is a no-op. */
    if (!p4_game_tables_overlay_count(NO_OWNER)) return;
    for (unsigned i = 0; i < P4_TABLE_OVERLAY_BANKS; ++i) {
        Overlay *overlay = &overlays[i];
        uint32_t base = 0, extent = 0;
        if (!overlay->layer || !banks[i].address || banks[i].address >= address + bytes ||
            address >= banks[i].address + banks[i].size) continue;
        int keeps = p4_game_tables_overlay_extent(&banks[i], &base, &extent) && base == overlay->base &&
            extent == overlay->bytes;
        /* The fresh copy is the new stock; the layer must still differ only in its fields. */
        for (uint32_t k = 0; keeps && banks[i].row_stride && k < extent; ++k) {
            const uint32_t column = k % banks[i].row_stride;
            if ((column < banks[i].field_offset || column >= banks[i].field_offset + banks[i].field_size) &&
                overlay->layer[k] != ((const uint8_t *)P4_G2H(base))[k])
                keeps = 0;
        }
        if (!keeps) {
            fprintf(stderr, "p4pc: table overlay: %s of mod %s dropped: the table was copied again with other "
                            "contents or is no longer the one the game reads\n", banks[i].key, overlay->owner_name);
            release(overlay);
            continue;
        }
        memcpy(overlay->stock, P4_G2H(base), extent);
        func_0043f810(P4_G2H(base), overlay->layer, extent);
    }
    update_observer();
}
void p4_game_tables_overlay_reset(void)
{
    /* Clear the observer first: a restore must never be re-overlaid. */
    p4_game_table_extent_observe(NULL, NULL);
    for (unsigned i = 0; i < P4_TABLE_OVERLAY_BANKS; ++i) restore(i);
}

/* The session-end restore rides the native save commit: every load and every
 * New Game reset commits before any mod's load callback is notified. */
static int encode(const P4ModSaveContext *context, P4ModSaveWriter *writer, void *user)
{
    (void)context; (void)writer; (void)user;
    return 1;
}
static int decode(const P4ModSaveContext *context, uint32_t schema, P4ModSaveReader *reader, void **staged, void *user)
{
    (void)context; (void)schema; (void)user;
    *staged = NULL;
    return reader ? -1 : 0;
}
static void commit(void *staged, void *user)
{
    (void)staged; (void)user;
    p4_game_tables_overlay_reset();
}
static void discard(void *staged, void *user) { (void)staged; (void)user; }
int p4_game_tables_overlay_session_register(void)
{
    if (session_registration) return 0;
    const P4ModSaveProvider provider = {
        .struct_size = sizeof provider, .abi_version = P4_MOD_SAVE_ABI_VERSION,
        .owner = "p4pc", .key = "table-overlay-session", .schema_version = 1, .flags = 0,
        .max_bytes = 16, .encode = encode, .decode = decode, .commit = commit, .discard = discard
    };
    return p4_mod_save_register(&provider, &session_registration) ? -1 : 0;
}
